mod solution;

fn main() {
    let cases = [
    (r#"n=6 edges=(0,1),(1,2),(1,3),(3,4),(3,5)"#, r#"1"#),
    (r#"n=5 edges=(0,1),(0,2),(0,3),(0,4)"#, r#"0"#),
    (r#"
n=5 edges=(0,1),(0,2),(0,3),(0,4)
"#, r#"0"#),
    (r#"  
n=6 edges=(0,1),(1,2),(1,3),(3,4),(3,5)
  "#, r#"1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS centroid-decomposition");
}
